const input = require("fs").readFileSync(0, "utf8");

const INT_MAX = 2 ** 31 - 1;
const INT_MIN = -(2 ** 31);
const ZERO = "0".charCodeAt(0);

function stringToInteger(s) {
  let i = 0;
  while (i < s.length && s[i] === " ") {
    i++;
  }
  let sign = 1;
  if (s[i] === "+" || s[i] === "-") {
    sign = s[i] === "-" ? -1 : 1;
    i++;
  }
  let value = 0;
  for (; i < s.length; i++) {
    const digit = s.charCodeAt(i) - ZERO;
    if (digit < 0 || digit > 9) {
      break;
    }
    value = value * 10 + digit;
    if (value > INT_MAX) {
      return sign === 1 ? INT_MAX : INT_MIN;
    }
  }
  // sign * 0 would be -0, which console.log prints as -0
  return value === 0 ? 0 : sign * value;
}

console.log(stringToInteger(input.split("\n")[0]));

