#include <cctype>
#include <cstddef>
#include <iostream>
#include <limits>
#include <string>

int stringToInteger(const std::string& s) {
    const int intMax = std::numeric_limits<int>::max();
    const int intMin = std::numeric_limits<int>::min();
    std::size_t i = 0;
    while (i < s.size() && s[i] == ' ') {
        i++;
    }
    int sign = 1;
    if (i < s.size() && (s[i] == '+' || s[i] == '-')) {
        sign = s[i] == '-' ? -1 : 1;
        i++;
    }
    // 64 bits hold any value up to intMax times 10 plus a digit, so one more
    // digit never overflows before the check below.
    long long value = 0;
    while (i < s.size() && std::isdigit(static_cast<unsigned char>(s[i]))) {
        value = value * 10 + (s[i] - '0');
        if (value > intMax) {
            return sign == 1 ? intMax : intMin;
        }
        i++;
    }
    return static_cast<int>(sign * value);
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::cout << stringToInteger(line) << "\n";
    return 0;
}

