package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
)

func stringToInteger(s string) int {
	i := 0
	for i < len(s) && s[i] == ' ' {
		i++
	}
	sign := int64(1)
	if i < len(s) && (s[i] == '+' || s[i] == '-') {
		if s[i] == '-' {
			sign = -1
		}
		i++
	}
	// s[i] is a byte, and digits are plain ASCII, so a byte range checks them.
	var value int64
	for i < len(s) && '0' <= s[i] && s[i] <= '9' {
		value = value*10 + int64(s[i]-'0')
		if value > math.MaxInt32 {
			if sign == 1 {
				return math.MaxInt32
			}
			return math.MinInt32
		}
		i++
	}
	return int(sign * value)
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	fmt.Println(stringToInteger(scanner.Text()))
}

